#!/usr/bin/env node
// Extract the loadable memory image of an ELF binary as {address: uint32LE} JSON.
// Usage: node extract.js /path/to/binary > out.json
'use strict';

const fs = require('fs');

const BASE = 0x400000; // load base for the image

function main() {
  const path = process.argv[2];
  if (!path) {
    process.stderr.write('usage: node extract.js <elf-binary>\n');
    process.exit(1);
  }
  const buf = fs.readFileSync(path);

  if (buf.length < 16 || buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    process.stderr.write('not an ELF file\n');
    process.exit(1);
  }

  const is64 = buf[4] === 2;
  const little = buf[5] === 1;

  const u16 = (o) => (little ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
  const u32 = (o) => (little ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
  const u64 = (o) => {
    const lo = little ? buf.readUInt32LE(o) : buf.readUInt32BE(o + 4);
    const hi = little ? buf.readUInt32LE(o + 4) : buf.readUInt32BE(o);
    return hi * 4294967296 + lo;
  };
  const uN = (o) => (is64 ? u64(o) : u32(o));

  // ELF header: e_phoff / e_phentsize / e_phnum
  const phoff = is64 ? u64(0x20) : u32(0x1c);
  const phentsize = is64 ? u16(0x36) : u16(0x2a);
  const phnum = is64 ? u16(0x38) : u16(0x2c);

  const PT_LOAD = 1;
  const segs = [];
  for (let i = 0; i < phnum; i++) {
    const p = phoff + i * phentsize;
    if (p + phentsize > buf.length) break;
    const type = u32(p);
    if (type !== PT_LOAD) continue;
    const offset = is64 ? u64(p + 0x08) : u32(p + 0x04);
    const vaddr = is64 ? u64(p + 0x10) : u32(p + 0x08);
    const filesz = is64 ? u64(p + 0x20) : u32(p + 0x10);
    if (filesz <= 0) continue;
    segs.push({ offset, vaddr, filesz });
  }
  // deterministic, ascending order by virtual address
  segs.sort((a, b) => a.vaddr - b.vaddr);

  const out = new Map();
  for (const s of segs) {
    const avail = Math.min(s.filesz, Math.max(0, buf.length - s.offset));
    for (let i = 0; i + 4 <= avail; i += 4) {
      const addr = BASE + s.vaddr + i;
      const val = little ? buf.readUInt32LE(s.offset + i) : buf.readUInt32BE(s.offset + i);
      out.set(addr, val);
    }
  }

  const keys = Array.from(out.keys()).sort((a, b) => a - b);
  const parts = [];
  for (const k of keys) parts.push(JSON.stringify(String(k)) + ':' + out.get(k));
  process.stdout.write('{' + parts.join(',') + '}\n');
}

main();
